-- Check how many records per robot in actuation_data and operation
SELECT COUNT(*) as total_actuation, COUNT(DISTINCT actdetref) as distinct_robots 
FROM actuation_data;

SELECT COUNT(*) as total_operation, COUNT(DISTINCT operbotdetref) as distinct_robots 
FROM operation;

-- Check how many records per robot in actuation_data
SELECT COUNT(*) as total_actuation, COUNT(DISTINCT actdetref) as distinct_robots 
FROM actuation_data;

-- Check how many records per robot in performance_and_safety
SELECT COUNT(*) as total_perf, COUNT(DISTINCT effectivenessrobot) as distinct_robots 
FROM performance_and_safety;

-- Check how many records per robot in maintenance_and_fault
SELECT COUNT(*) as total_maint, COUNT(DISTINCT upkeeprobot) as distinct_robots 
FROM maintenance_and_fault;

-- Check how many records per robot in operation
SELECT COUNT(*) as total_op, COUNT(DISTINCT operbotdetref) as distinct_robots 
FROM operation;

-- Let's check how many records per robot in robot_record
SELECT COUNT(*) as total_records, COUNT(DISTINCT botcode) as distinct_robots 
FROM robot_record;

-- Check robot_details count
SELECT COUNT(*) as total_det, COUNT(DISTINCT botdetreg) as distinct_robots 
FROM robot_details;

-- Check if there are any views or additional tables that might define TWR/TPC
SELECT table_name FROM information_schema.tables 
WHERE table_schema = 'public' AND table_type = 'VIEW';

-- Check toolchangecount distribution
SELECT MIN(toolchangecount), MAX(toolchangecount), AVG(toolchangecount) 
FROM performance_and_safety;

-- Check progcyclecount distribution
SELECT MIN(progcyclecount), MAX(progcyclecount), AVG(progcyclecount) 
FROM operation;

-- Check if robot_record.recreg matches with other tables directly
SELECT COUNT(*) FROM robot_record rr 
JOIN operation op ON rr.recreg = op.operrecref;

SELECT COUNT(*) FROM robot_record rr 
JOIN performance_and_safety ps ON rr.recreg = ps.effectivenessrobot;

-- Check if robot_record.recreg matches with performance_and_safety
SELECT COUNT(*) FROM robot_record rr 
JOIN performance_and_safety ps ON rr.recreg = ps.effectivenessrobot;
